reference_solution:
def minimum_one_cover_area(grid):
    rows=[];columns=[]
    for row,line in enumerate(grid):
        for column,value in enumerate(line):
            if value:rows.append(row);columns.append(column)
    return (max(rows)-min(rows)+1)*(max(columns)-min(columns)+1)

